function activate(name){$$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.panel===name));$$('.panel').forEach(x=>x.classList.toggle('active',x.id==='panel-'+name));if(!EMBEDDED)window.scrollTo({top:0,behavior:'smooth'});}
function unique(items,key){return [...new Set(items.map(x=>String(x[key]??'').trim()).filter(Boolean))];}
